package com.ssafy.yumyumcoach.ui;

import com.ssafy.yumyumcoach.domain.*;
import com.ssafy.yumyumcoach.manager.*;
import com.ssafy.yumyumcoach.util.*;
import java.time.LocalDate;
import java.util.*;

public class MenuUI {
    private final AuthManager auth; private final UserManager users; private final MealManager meals; private final ChallengeManager challenges; private final CommunityManager community; private final CoachingManager coaching; private final Scanner scanner=new Scanner(System.in); private final InputUtil in=new InputUtil(scanner);
    public MenuUI(AuthManager a,UserManager u,MealManager m,ChallengeManager ch,CommunityManager c,CoachingManager co){auth=a;users=u;meals=m;challenges=ch;community=c;coaching=co;}
    public void run(){System.out.println("\n=== 냠냠코치 | 식단 분석 기반 건강 코칭 ===");System.out.println("AI 모드: "+coaching.providerInfo());boolean on=true;while(on){try{on=auth.loggedIn()?memberMenu():guestMenu();}catch(Exception e){System.out.println("[처리 실패] "+e.getMessage());}}System.out.println("냠냠코치를 종료합니다.");}
    private boolean guestMenu(){System.out.println("\n1.로그인 2.회원가입 0.종료");return switch(in.integer("선택: ",0,2)){case 1->{login();yield true;}case 2->{register();yield true;}default->false;};}
    private boolean memberMenu(){User u=auth.require();System.out.printf("\n[%s님] 1.식단 2.내 정보 3.팔로우 4.챌린지 5.커뮤니티 6.AI 코칭 7.성능 데모 8.로그아웃 0.종료%n",u.getName());return switch(in.integer("선택: ",0,8)){case 1->{mealMenu(u);yield true;}case 2->{profileMenu(u);yield true;}case 3->{followMenu(u);yield true;}case 4->{challengeMenu(u);yield true;}case 5->{communityMenu(u);yield true;}case 6->{aiMenu(u);yield true;}case 7->{performanceDemo(u);yield true;}case 8->{auth.logout();System.out.println("로그아웃했습니다.");yield true;}default->false;};}
    private void login(){String id=in.text("아이디: "),pw=in.text("비밀번호: ");System.out.println(auth.login(id,pw)?"로그인 성공":"아이디/비밀번호 또는 활성 상태를 확인하세요.");}
    private void register(){User u=users.register(in.text("아이디: "),in.text("비밀번호(4자 이상): "),in.text("이름: "),in.integer("나이: ",1,120),in.text("성별(남/여/기타): "),in.number("키(cm): ",50),in.number("몸무게(kg): ",10),in.text("질환(없음 가능): "),in.text("건강 목표: "));System.out.println("가입 완료: "+u);}
    private void mealMenu(User u){System.out.println("\n[F201~F205] 1.작성 2.목록/상세 3.수정 4.삭제 5.분석 6.음식검색 7.추천 0.뒤로");switch(in.integer("선택: ",0,7)){case 1->createMeal(u);case 2->showMeals(u);case 3->updateMeal(u);case 4->{long id=in.longValue("삭제할 식단 ID: ");meals.delete(id,u.getId());System.out.println("삭제했습니다.");}case 5->{Meal m=ownedMeal(u,in.longValue("분석할 식단 ID: "));System.out.println(meals.analyze(m,u));}case 6->{var r=meals.searchFoods(in.text("검색어: "));r.result().forEach(f->System.out.println(f.summary()));System.out.println(r.report());}case 7->{var r=meals.recommend(u,5);r.result().forEach(f->System.out.println(f.summary()));System.out.println(r.report());}default->{}}}
    private void createMeal(User u){Meal m=meals.create(u.getId(),in.date("날짜 "),in.text("구분(아침/점심/저녁/간식): "),readEntries(),in.text("메모: "));System.out.println("작성 완료: "+m);}
    private void showMeals(User u){List<Meal> list=meals.list(u.getId());if(list.isEmpty()){System.out.println("식단 기록이 없습니다.");return;}list.forEach(System.out::println);if(in.yes("상세 조회")){Meal m=ownedMeal(u,in.longValue("식단 ID: "));System.out.println(m);m.getEntries().forEach(e->System.out.printf(" - %s %.1f회 %.1fkcal%n",e.foodName(),e.servings(),e.calories()));}}
    private void updateMeal(User u){Meal m=ownedMeal(u,in.longValue("수정할 식단 ID: "));LocalDate d=in.yes("날짜를 변경할까요")?in.date("새 날짜 "):m.getDate();String type=in.optional("구분(Enter=유지)",m.getMealType());List<MealEntry> e=in.yes("음식 목록을 다시 입력할까요")?readEntries():m.getEntries();String memo=in.optional("메모(Enter=유지)",m.getMemo());meals.update(m,d,type,e,memo);System.out.println("수정했습니다.");}
    private List<MealEntry> readEntries(){List<MealEntry> out=new ArrayList<>();System.out.println("음식 ID 목록은 검색 메뉴 또는 data/foods.csv에서 확인할 수 있습니다.");do{String id=in.text("음식 ID: ");double s=in.number("섭취 횟수(1회 제공량 기준): ",0.1);out.add(meals.entry(id,s));}while(in.yes("음식을 더 추가할까요"));return out;}
    private Meal ownedMeal(User u,long id){return meals.findOwned(id,u.getId()).orElseThrow(()->new IllegalArgumentException("본인의 식단을 찾을 수 없습니다."));}
    private void profileMenu(User u){System.out.println("\n[F207~F209] 1.조회 2.수정 3.탈퇴 0.뒤로");switch(in.integer("선택: ",0,3)){case 1->System.out.println(u);case 2->{users.update(u,in.optional("이름",u.getName()),in.integer("나이: ",1,120),in.optional("성별",u.getGender()),in.number("키(cm): ",50),in.number("몸무게(kg): ",10),in.optional("질환",u.getDisease()),in.optional("목표",u.getGoal()));System.out.println("수정했습니다.");}case 3->{if(in.yes("정말 비활성화할까요")){users.deactivate(u);auth.logout();System.out.println("회원이 비활성화되었습니다.");}}default->{}}}
    private void followMenu(User u){System.out.println("\n[F211] 1.전체회원 2.팔로우 3.언팔로우 4.내 목록 0.뒤로");switch(in.integer("선택: ",0,4)){case 1->users.activeUsers().forEach(System.out::println);case 2->{users.follow(u,in.text("대상 ID: "));System.out.println("팔로우했습니다.");}case 3->{users.unfollow(u,in.text("대상 ID: "));System.out.println("취소했습니다.");}case 4->users.following(u).forEach(System.out::println);default->{}}}
    private void challengeMenu(User u){System.out.println("\n[F212~F213] 1.목록 2.등록 3.삭제 4.참여 5.달성도수정 6.내 참여 0.뒤로");switch(in.integer("선택: ",0,6)){case 1->challenges.list().forEach(System.out::println);case 2->{Challenge c=challenges.create(in.text("제목: "),in.text("설명: "),in.date("시작일 "),in.date("종료일 "),in.text("이미지 경로/URL: "));System.out.println("등록: "+c);}case 3->{challenges.delete(in.longValue("챌린지 ID: "));System.out.println("삭제했습니다.");}case 4->{var p=challenges.join(in.longValue("챌린지 ID: "),u.getId());System.out.println("참여 완료, 달성도 "+p.getProgress()+"%");}case 5->{challenges.progress(in.longValue("챌린지 ID: "),u.getId(),in.integer("달성도(%): ",0,100));System.out.println("갱신했습니다.");}case 6->challenges.mine(u.getId()).forEach(p->System.out.printf("챌린지 #%d: %d%%%n",p.getChallengeId(),p.getProgress()));default->{}}}
    private void communityMenu(User u){System.out.println("\n[F214~F215] 1.글목록 2.글작성 3.글수정 4.글삭제 5.글검색 6.댓글목록 7.댓글작성 8.댓글수정 9.댓글삭제 0.뒤로");switch(in.integer("선택: ",0,9)){case 1->community.posts().forEach(System.out::println);case 2->System.out.println("작성: "+community.createPost(u.getId(),in.text("게시판(식단리뷰/전문가/자유): "),in.text("제목: "),in.text("내용: ")));case 3->{community.updatePost(in.longValue("글 ID: "),u.getId(),in.text("새 제목: "),in.text("새 내용: "));System.out.println("수정했습니다.");}case 4->{community.deletePost(in.longValue("글 ID: "),u.getId());System.out.println("삭제했습니다.");}case 5->{var r=community.search(in.text("검색어: "));r.result().forEach(System.out::println);System.out.println(r.report());}case 6->community.comments(in.longValue("글 ID: ")).forEach(System.out::println);case 7->System.out.println("작성: "+community.createComment(in.longValue("글 ID: "),u.getId(),in.text("댓글: ")));case 8->{community.updateComment(in.longValue("댓글 ID: "),u.getId(),in.text("새 댓글: "));System.out.println("수정했습니다.");}case 9->{community.deleteComment(in.longValue("댓글 ID: "),u.getId());System.out.println("삭제했습니다.");}default->{}}}
    private void aiMenu(User u){System.out.println("\n[F216~F217] 1.AI 식단 분석 2.AI 운동 코칭 0.뒤로");switch(in.integer("선택: ",0,2)){case 1->System.out.println(coaching.mealCoach(u,ownedMeal(u,in.longValue("식단 ID: "))));case 2->System.out.println(coaching.exerciseCoach(u));default->{}}}
    private void performanceDemo(User u){System.out.println("\n=== 알고리즘 성능 측정 ===");var s=meals.searchFoods("밥");System.out.println("KMP 결과 "+s.result().size()+"건 / "+s.report());var m=meals.sortByCalories(u.getId());System.out.println("병합 정렬 결과 "+m.result().size()+"건 / "+m.report());var r=meals.recommend(u,5);System.out.println("추천 결과 "+r.result().size()+"건 / "+r.report());}
}
